def _parse_json(text: str) -> dict:
    def unique_keys(pairs):
        obj = {}
        for key, value in pairs:
            if key in obj:
                raise JudgeValidationError(f"duplicate JSON key: {key}")
            obj[key] = value
        return obj

    text = re.sub(r"<think>.*?</think>", "", text or "", flags=re.S)
